<template><div class="biz-page"><PageHeader eyebrow="数据中心 · 库存效率" title="库存周转率" description="识别周转缓慢和呆滞积压商品"/><section class="biz-card toolbar"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD"/><el-switch v-model="stagnantOnly" active-text="只看呆滞商品"/><el-button type="primary" :loading="loading" @click="load">查询</el-button></section><section class="biz-card"><el-table v-loading="loading" :data="displayRows" border><el-table-column prop="productName" label="商品" min-width="190"/><el-table-column prop="soldQuantity" label="销量" width="90" align="right"/><el-table-column prop="beginningStock" label="期初库存" width="110" align="right"/><el-table-column prop="endingStock" label="期末库存" width="110" align="right"/><el-table-column prop="averageStock" label="平均库存" width="110" align="right"/><el-table-column label="周转次数" width="115" align="right"><template #default="{row}"><b>{{Number(row.turnoverTimes).toFixed(2)}}</b></template></el-table-column><el-table-column label="识别结果" width="110" align="center"><template #default="{row}"><el-tag :type="row.stagnant?'danger':'success'">{{row.stagnant?'呆滞':'正常'}}</el-tag></template></el-table-column></el-table></section></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{statisticsApi}from'../../api/statistics';import type{InventoryTurnover}from'../../types/statistics';const now=new Date(),start=new Date();start.setDate(now.getDate()-29);const toDate=(d:Date)=>d.toISOString().slice(0,10);const range=ref([toDate(start),toDate(now)]),rows=ref<InventoryTurnover[]>([]),loading=ref(false),stagnantOnly=ref(false);const displayRows=computed(()=>stagnantOnly.value?rows.value.filter(x=>x.stagnant):rows.value);async function load(){if(range.value.length!==2)return;loading.value=true;try{rows.value=await statisticsApi.getInventoryTurnover({startDate:range.value[0],endDate:range.value[1]})??[]}finally{loading.value=false}}onMounted(load)</script><style scoped>.toolbar{margin-bottom:14px;display:flex;align-items:center;gap:16px}</style>
